from pathlib import Path
p=Path('.scratch/frontend-loop')
spec='''graph2note 是本地运行的手稿电子化与知识管理工具。本轮针对已有前端的视觉和交互体验，不新增后台业务。主要使用者是在笔记本电脑上处理手稿、PDF 和知识归档的人；他们会反复在文档库、编辑器、时间轴、图谱和问答之间切换，而不是只看一次宣传页面。因此设计的首要目标是减少找入口和理解状态的成本，保留文档内容的主角地位。\n三个方向统一为 1440×900 的桌面网页原型，并兼顾 390px 窄窗口。初稿统一展示空文档库，内容取自现有 index.html，不虚构文档、统计或处理结果。包含 graph2note 文字品牌、搜索入口、新解析、七个主要导航、集合以及设置、导出和修复入口。主区域包括文档库标题、时间筛选、密度切换、尚未导入的空状态与下一步操作。\n视觉气质应清楚、沉稳、耐看；这是持续工作的界面，避免宣传式巨型标题、装饰数据、无信息价值的图片、炫光和满屏装饰图标。正文至少14px，标签至少12px，正文对比度至少4.5:1。现有品牌是文字 graph2note，来源为仓库首页；尚未发现正式字体或图形标识规范，不自行声称存在官方图形标识。工具型空状态不需要内容照片，图片需求为无，现有界面截图作为基线证据。\n方向A采用轮盘第13项的深色工作区结构，但移除与长期阅读不符的炫光，明确是功能适配；方向B参考已核实的 Bear 侧栏与阅读排印方法，采用紧凑导航、纸感内容和列表阅读；方向C采用原研哉式的信息减法思考，以手稿到知识的整理过程为母题，构造水平导航与档案索引，非本人作品或合作声明。三版骨架必须有区别，而不是只换色。\n页面五问：叙事角色为工作入口；观众距离为笔记本约50cm；视觉温度为安静而有明确状态；容量为导航、搜索、筛选和空状态同时出现在首屏；视觉母题取自手稿归档的纸张、目录与索引。后续按每个标签页的真实任务分别调整，保留路由、API和自动保存等业务契约。当前没有方向批准，不把任何方向写入生产样式。验证时巡检全部标签页，并记录错误、溢出与截图；视觉判断需要肉眼检查，自动脚本不能冒充审美评分。'''
(p/'design-spec.md').write_text(spec)
(p/'brand-spec.md').write_text('来源：graph2note/webstatic/index.html 与 style.css。现有文字品牌 graph2note；底色 #f6f7f9，面板 #ffffff，正文 #1f2328，强调色 #2563eb。未发现正式图形 logo，沿用真实文字品牌。无内容照片需求。基线截图见 evidence。')
nav=['文档库','时间轴','知识图谱','数据看板','待整理','标签词表','问答']
base='''*{box-sizing:border-box}body{margin:0;font:15px/1.6 -apple-system,"PingFang SC",sans-serif;color:var(--ink);background:var(--bg)}button,input{font:inherit}button{cursor:pointer}button,a{touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:3px}button{color:inherit;border:1px solid var(--line);background:transparent;border-radius:6px;padding:9px 16px}a{color:inherit;text-decoration:none}h1{font-size:36px;line-height:1.3;font-weight:600;letter-spacing:-1px}h2{font-size:24px}p{color:var(--muted)}.brand{font:600 25px Georgia,serif;letter-spacing:-1px}.shell{min-height:100vh;display:grid;grid-template-columns:220px 1fr}.side{padding:32px 22px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:32px}.nav{display:flex;flex-direction:column;gap:4px}.nav a{padding:10px 14px;border-radius:5px}.nav .active{color:var(--accent);background:var(--soft);font-weight:600}.caption{font-size:12px;letter-spacing:2px;color:var(--muted)}.secondary{margin-top:auto}.top{height:88px;padding:22px 40px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:20px}.top input{border:0;background:transparent;color:inherit;width:100%;outline-offset:6px}.top form{flex:1}.primary{background:var(--accent);color:var(--on);border-color:var(--accent)}.content{padding:46px 56px}.heading{display:flex;align-items:end;justify-content:space-between}.heading h1{margin:12px 0}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:28px 0;padding-bottom:24px;border-bottom:1px solid var(--line)}.filters button{border:0;font-size:14px}.filters .selected{background:var(--soft);color:var(--accent)}.empty{min-height:390px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border:1px solid var(--line);background:var(--panel)}.empty p{max-width:440px;margin:0 0 26px}.folio{font:italic 58px Georgia,serif;color:var(--accent);margin-bottom:12px}.footer{margin-top:24px;display:flex;justify-content:space-between;color:var(--muted);font-size:12px}.notice{padding:18px;border:1px solid var(--line);margin-top:18px}.hidden{display:none}.density{font-size:12px;color:var(--muted)}@media(max-width:700px){.shell{display:block}.side{padding:20px;border-right:0;border-bottom:1px solid var(--line)}.nav{flex-direction:row;overflow:auto}.nav a{white-space:nowrap}.side .collection,.secondary{display:none}.top{padding:16px 20px}.content{padding:28px 20px}.heading{display:block}.empty{padding:24px}.footer{gap:20px}}'''
variants={
'a-studio':(':root{--bg:#171918;--panel:#202320;--ink:#eef1ec;--muted:#b5beb3;--line:#414940;--accent:#c7dab7;--on:#172015;--soft:#303b2e}.side{background:#1b1f1b}.empty{border-radius:12px}.content{max-width:1260px}.folio{font-style:normal}.heading h1{font-family:Georgia,"Songti SC",serif}', 'A · 深色工作台','MANUSCRIPT WORKSPACE'),
'b-reading':(':root{--bg:#fcfaf6;--panel:#fffefa;--ink:#302d29;--muted:#69615a;--line:#ddd8cf;--accent:#a44633;--on:#fff;--soft:#f1e3dc}.shell{grid-template-columns:190px 1fr}.side{background:#eeeae2}.content{max-width:1100px;margin:auto}.empty{border:0;border-top:3px solid var(--ink);align-items:flex-start;text-align:left;padding:38px 46px;min-height:380px}.folio{font-family:Georgia,serif}.heading h1{font-family:"Songti SC",Georgia,serif}.top{background:var(--panel)}', 'B · 纸感阅读室','LOCAL KNOWLEDGE LIBRARY'),
'c-index':(':root{--bg:#fff;--panel:#fff;--ink:#222b35;--muted:#596572;--line:#d6dde2;--accent:#2459a6;--on:#fff;--soft:#eaf1fa}.shell{display:block}.side{display:grid;grid-template-columns:180px 1fr;align-items:center;padding:24px 48px;gap:24px;border-bottom:1px solid var(--line)}.nav{flex-direction:row;justify-content:flex-end}.nav a{white-space:nowrap;padding:8px 12px}.collection,.secondary{display:none}.top{height:72px;padding:16px 56px}.content{max-width:1280px;margin:auto}.empty{display:grid;grid-template-columns:240px 1fr;text-align:left;padding:50px;gap:12px;border-left:0;border-right:0}.folio{grid-row:1/4;font-size:100px;font-style:normal}.empty h2,.empty p{margin:0}.empty button{justify-self:start;align-self:start}.heading h1{font-family:Georgia,"Songti SC",serif}@media(max-width:900px){.side{display:block;padding:20px}.nav{justify-content:flex-start;overflow:auto}.empty{display:flex;align-items:flex-start;padding:24px}.folio{font-size:54px}}','C · 知识索引','FROM MANUSCRIPT TO KNOWLEDGE')}
for filename,(css,title,kicker) in variants.items():
    links=''.join(f'<a href="#preview" data-preview="{n}" class="{"active" if i==0 else ""}">{n}</a>' for i,n in enumerate(nav))
    html=f'''<!doctype html><html lang="zh-CN"><!-- Assumptions: empty local library; existing product labels; no fabricated documents. Reasoning: see ../design-spec.md. Prototype only; actions disclose preview scope. --><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · graph2note</title><style>{base}{css}</style><body><div class="shell"><aside class="side"><a class="brand" href="#">graph2note</a><nav class="nav" aria-label="主导航">{links}</nav><div class="collection"><div class="caption">集合</div><p>按主题整理你的文档</p><button data-preview="新建集合">＋ 新建集合</button></div><div class="secondary"><p>本地工作空间</p><a data-preview="LLM 设置" href="#preview">LLM 设置</a><br><a data-preview="导出 Vault" href="#preview">导出 Vault</a><br><a data-preview="修复报告" href="#preview">修复报告</a></div></aside><div><header class="top"><form id="search"><input aria-label="搜索文档" placeholder="搜索文档 / PDF" type="search"></form><button class="primary" data-preview="新解析">＋ 新解析</button></header><main class="content"><div class="caption">{kicker}</div><div class="heading"><div><h1>本地文档库</h1><p>从一页手稿开始，留下可以继续使用的知识。</p></div><div class="density">紧凑 / 舒适</div></div><div class="filters" aria-label="文档过滤"><button class="selected" aria-pressed="true">全部</button><button aria-pressed="false">今日新增</button><button aria-pressed="false">本周新增</button><button aria-pressed="false">最近编辑</button></div><section class="empty"><div class="folio" aria-hidden="true">Aa</div><h2>你的第一份手稿，从这里开始。</h2><p>还没有文档。上传一张手稿图片开始解析，随后在文档库中整理、阅读与编辑。</p><button class="primary" data-preview="新解析">上传手稿</button></section><div class="footer"><span>原图 · 识别结果 · Markdown</span><span>内容保存在本地</span></div><div id="notice" class="notice hidden" role="status"></div></main></div></div><script>const notice=document.querySelector('#notice');function show(t){{notice.textContent=t;notice.classList.remove('hidden')}}document.querySelectorAll('[data-preview]').forEach(e=>e.onclick=()=>show(e.dataset.preview+'：当前为设计方向初稿，业务功能在现有应用中使用。'));document.querySelectorAll('.filters button').forEach(e=>e.onclick=()=>{{document.querySelectorAll('.filters button').forEach(b=>{{b.classList.remove('selected');b.setAttribute('aria-pressed','false')}});e.classList.add('selected');e.setAttribute('aria-pressed','true');show(e.textContent+'：当前文档库为空。')}});document.querySelector('#search').onsubmit=e=>{{e.preventDefault();show('当前文档库为空，暂无搜索结果。')}};</script></body></html>'''
    (p/'design-demos'/f'{filename}.html').write_text(html)
